n = int(input("Enter a number: "))

# if...else
if n % 2 == 0:
    print(n, "is EVEN")
else:
    print(n, "is ODD")

# if...elif...else
if n > 0:
    print(n, "is POSITIVE")
elif n < 0:
    print(n, "is NEGATIVE")
else:
    print("The number is ZERO")

# conditional expression (ternary)
kind = "even" if n % 2 == 0 else "odd"
print("Using ternary:", kind)

a = int(input("Enter a: "))
b = int(input("Enter b: "))
c = int(input("Enter c: "))

if a >= b:
    if a >= c:
        largest = a
    else:
        largest = c
else:
    if b >= c:
        largest = b
    else:
        largest = c
print("Largest (nested if)     :", largest)

if a >= b and a >= c:
    largest = a
elif b >= c:
    largest = b
