n = int(input("Enter a number: "))
if n < 2:
    print(n, "is not prime")
else:
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            print(f"{n} is NOT prime (divisible by {i})")
            break
    else:
        print(n, "is PRIME")

print("Primes between 1 and 50:")
for num in range(2, 51):
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            break
    else:
        print(num, end=" ")
print()

print("break    :", end=" ")
for i in range(1, 8):
    if i == 4:
        break             # exit the loop
    print(i, end=" ")
print()

print("continue :", end=" ")
for i in range(1, 8):
    if i == 4:
        # skip this iteration
        continue
    print(i, end=" ")
print()

print("pass     :", end=" ")
for i in range(1, 8):
    if i == 4:
        # do nothing (placeholder)
        pass
    print(i, end=" ")
print()

def check(n):
    if n < 0:
        # return ends the function
        return "negative"
    return "non-negative"
print("return   :", check(-5), check(3))

# infinite loop with exit
while True:
    s = input("Type 'q' to quit: ")
    if s == "q":
        print("Bye!")
        break

n = int(input("Enter rows: "))

print("Right triangle:")
for i in range(1, n + 1):
    for j in range(i):
        print("*", end=" ")
    print()

print("Number triangle:")
for i in range(1, n + 1):
    for j in range(1, i + 1):
        print(j, end=" ")
    print()

print("Pyramid:")
for i in range(1, n + 1):
    print(" " * (n - i) + "* " * i)

print("Floyd's triangle:")
k = 1
for i in range(1, n + 1):
    for j in range(i):
        print(f"{k:3}", end="")
        k += 1
    print()

